/* ============================================================
   Stock Dashboard — stylesheet
   ============================================================ */

*, *::before, *::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  font-family: "Inter", "Segoe UI", Arial, sans-serif;
  background: #0f1117;
  color: #e2e8f0;
  min-height: 100vh;
}

/* ---------- Page header ---------- */
header {
  padding: 18px 32px 14px;
  border-bottom: 1px solid #1e2233;
  background: #12151f;
}

header h1 {
  margin: 0;
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: #f0f4ff;
}

header p {
  margin: 4px 0 0;
  font-size: 0.8rem;
  color: #7a8499;
}

/* ---------- Main layout ---------- */
#app {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  gap: 0;
  padding: 20px 24px;
  min-height: calc(100vh - 70px);
}

/* ---------- Panels ---------- */
.panel {
  background: #161b27;
  border: 1px solid #1e2233;
  border-radius: 10px;
  overflow: hidden;
}

.panel-title {
  padding: 12px 18px;
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: #7a8499;
  border-bottom: 1px solid #1e2233;
  background: #12151f;
}

/* ---------- Bubble chart panel ---------- */
#chart-panel {
  flex: 0 0 auto;
  width: 620px;
  margin-right: 20px;
}

#chart-container {
  position: relative;
  padding: 8px;
}

#bubble-svg {
  display: block;
}

/* ---------- Legend ---------- */
#legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  padding: 10px 18px 14px;
  border-top: 1px solid #1e2233;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.75rem;
  color: #a0aec0;
  cursor: default;
  user-select: none;
}

.legend-swatch {
  width: 11px;
  height: 11px;
  border-radius: 50%;
  flex-shrink: 0;
}

/* ---------- Bubble styles ---------- */
.bubble {
  cursor: pointer;
  transition: filter 0.15s;
}

.bubble:hover {
  filter: brightness(1.25);
}

.bubble.selected circle {
  stroke: #ffffff;
  stroke-width: 2.5px;
}

.bubble-label {
  pointer-events: none;
  font-weight: 600;
  fill: rgba(255,255,255,0.92);
  text-anchor: middle;
  dominant-baseline: central;
  letter-spacing: 0.01em;
}

/* ---------- Tooltip ---------- */
#tooltip {
  position: fixed;
  padding: 9px 13px;
  background: rgba(15, 17, 26, 0.95);
  border: 1px solid #2d3550;
  border-radius: 7px;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.15s;
  z-index: 9999;
  max-width: 240px;
  line-height: 1.5;
  box-shadow: 0 4px 20px rgba(0,0,0,0.5);
}

#tooltip.visible {
  opacity: 1;
}

.tt-ticker {
  font-size: 0.92rem;
  font-weight: 700;
  color: #f0f4ff;
}

.tt-name {
  font-size: 0.78rem;
  color: #a0aec0;
  margin-top: 2px;
}

.tt-sector {
  font-size: 0.75rem;
  color: #7a8499;
  margin-top: 4px;
}

.tt-sector span {
  display: inline-block;
  padding: 1px 7px;
  border-radius: 10px;
  font-weight: 600;
  font-size: 0.7rem;
  color: #fff;
}

/* ---------- Table panel ---------- */
#table-panel {
  flex: 1 1 auto;
  min-width: 0;
}

#table-wrapper {
  overflow-y: auto;
  max-height: 580px;
}

/* Scrollbar styling */
#table-wrapper::-webkit-scrollbar {
  width: 6px;
}
#table-wrapper::-webkit-scrollbar-track {
  background: #12151f;
}
#table-wrapper::-webkit-scrollbar-thumb {
  background: #2d3550;
  border-radius: 3px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.82rem;
}

thead th {
  position: sticky;
  top: 0;
  background: #12151f;
  padding: 10px 14px;
  text-align: left;
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #5a6480;
  border-bottom: 1px solid #1e2233;
  z-index: 10;
  white-space: nowrap;
}

tbody tr {
  cursor: pointer;
  border-bottom: 1px solid #1a1f2e;
  transition: background 0.12s;
}

tbody tr:hover {
  background: #1e2538;
}

tbody tr.selected {
  background: #1e3060;
}

tbody tr.selected td {
  color: #e8f0ff;
}

tbody td {
  padding: 9px 14px;
  color: #c5cedf;
  white-space: nowrap;
}

.td-ticker {
  font-weight: 700;
  color: #e2e8f0;
  font-size: 0.85rem;
  letter-spacing: 0.03em;
}

.td-name {
  color: #a0aec0;
  font-size: 0.8rem;
  max-width: 200px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.td-sector {
  white-space: nowrap;
}

.sector-badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 0.7rem;
  font-weight: 600;
  color: #fff;
}

.td-mcap {
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: #a0aec0;
  font-size: 0.8rem;
}

tbody tr.selected .td-mcap {
  color: #c5d8ff;
}

/**
 * Stock Dashboard — visualization.js
 *
 * Renders:
 *   1. Bubble chart (D3 force simulation, sector-clustered)
 *   2. Data table (all 50 stocks)
 *
 * Cross-linked: clicking a bubble highlights the table row and vice-versa.
 *
 * Data: /data/stock-descriptions.csv
 * Lib:  D3 v6 (locally vendored)
 */

(function () {
  "use strict";

  /* ============================================================
     CONFIG
     ============================================================ */
  const CHART_W = 600;
  const CHART_H = 560;

  // Sector display order (determines legend order & cluster positions)
  const SECTOR_ORDER = [
    "Information Technology",
    "Industry",
    "Energy",
    "Financial",
    "ETF",
  ];

  // Visually distinct, dark-theme-friendly palette
  const SECTOR_COLOR = {
    "Information Technology": "#4f8ef7",
    "Industry":               "#f7a14f",
    "Energy":                 "#f74f4f",
    "Financial":              "#4fca87",
    "ETF":                    "#b06cf7",
  };

  // Cluster target positions (cx, cy) for each sector inside the SVG
  // Arranged in a pentagon-ish layout, all comfortably inside the chart area.
  const SECTOR_CLUSTER = {
    "Information Technology": { x: CHART_W * 0.27, y: CHART_H * 0.27 },
    "Industry":               { x: CHART_W * 0.73, y: CHART_H * 0.27 },
    "Energy":                 { x: CHART_W * 0.20, y: CHART_H * 0.72 },
    "Financial":              { x: CHART_W * 0.76, y: CHART_H * 0.70 },
    "ETF":                    { x: CHART_W * 0.50, y: CHART_H * 0.51 },
  };

  // Radius range (pixels) for market-cap bubbles
  const R_MIN = 14;
  const R_MAX = 50;
  const R_ETF = 22; // fixed radius for ETFs (no market cap)

  /* ============================================================
     FORMAT HELPERS
     ============================================================ */
  function formatMarketCap(raw) {
    if (!raw || raw === "") return "—";
    const v = +raw;
    if (isNaN(v)) return "—";
    if (v >= 1e12) return (v / 1e12).toFixed(2) + "T";
    if (v >= 1e9)  return (v / 1e9).toFixed(1)  + "B";
    if (v >= 1e6)  return (v / 1e6).toFixed(1)  + "M";
    return v.toLocaleString();
  }

  /* ============================================================
     MAIN — load CSV then render
     ============================================================ */
  d3.csv("data/stock-descriptions.csv").then(function (rawData) {
    // Normalise field names (the CSV has a leading unnamed index column)
    const data = rawData.map(function (d) {
      return {
        ticker:    (d["ticker"] || "").trim().toUpperCase(),
        sector:    (d["sector"] || "").trim(),
        name:      (d["full name"] || "").trim(),
        marketCap: d["marketCap"] ? +d["marketCap"] : null,
        country:   (d["country"] || "").trim(),
        website:   (d["website"] || "").trim(),
        isETF:     (d["sector"] || "").trim() === "ETF",
      };
    });

    // Deterministic sort: sector order then ticker alpha
    data.sort(function (a, b) {
      const si = SECTOR_ORDER.indexOf(a.sector) - SECTOR_ORDER.indexOf(b.sector);
      if (si !== 0) return si;
      return a.ticker.localeCompare(b.ticker);
    });

    renderBubbleChart(data);
    renderTable(data);
  });

  /* ============================================================
     BUBBLE CHART
     ============================================================ */
  function renderBubbleChart(data) {
    // --- radius scale ---
    const caps = data.filter(function (d) { return d.marketCap !== null; })
                     .map(function (d) { return d.marketCap; });
    const capExtent = d3.extent(caps);

    const rScale = d3.scaleSqrt()
      .domain(capExtent)
      .range([R_MIN, R_MAX])
      .clamp(true);

    // Assign radii
    data.forEach(function (d) {
      d.r = d.isETF ? R_ETF : rScale(d.marketCap);
    });

    // --- SVG ---
    const svg = d3.select("#bubble-svg")
      .attr("width",   CHART_W)
      .attr("height",  CHART_H)
      .attr("viewBox", "0 0 " + CHART_W + " " + CHART_H);

    // Background
    svg.append("rect")
      .attr("width",  CHART_W)
      .attr("height", CHART_H)
      .attr("fill",   "#161b27");

    // --- Force simulation ---
    // Place nodes initially at their cluster target with a small grid offset
    // (deterministic, avoids random initial positions)
    const sectorCounts = {};
    data.forEach(function (d) {
      sectorCounts[d.sector] = (sectorCounts[d.sector] || 0) + 1;
    });
    const sectorIdx = {};
    SECTOR_ORDER.forEach(function (s) { sectorIdx[s] = 0; });

    data.forEach(function (d) {
      const target = SECTOR_CLUSTER[d.sector];
      const i = sectorIdx[d.sector]++;
      const count = sectorCounts[d.sector];
      // Spiral-like placement around cluster centre
      const angle = (i / count) * 2 * Math.PI;
      const spread = Math.min(d.r * 3, 60);
      d.x = target.x + Math.cos(angle) * spread;
      d.y = target.y + Math.sin(angle) * spread;
    });

    const simulation = d3.forceSimulation(data)
      .force("x", d3.forceX(function (d) { return SECTOR_CLUSTER[d.sector].x; }).strength(0.18))
      .force("y", d3.forceY(function (d) { return SECTOR_CLUSTER[d.sector].y; }).strength(0.18))
      .force("collide", d3.forceCollide(function (d) { return d.r + 2; }).strength(0.9))
      .force("charge", d3.forceManyBody().strength(-8))
      .stop();

    // Run a fixed number of ticks for determinism
    simulation.tick(300);

    // Clamp positions so no bubble escapes the SVG
    data.forEach(function (d) {
      d.x = Math.max(d.r + 4, Math.min(CHART_W - d.r - 4, d.x));
      d.y = Math.max(d.r + 4, Math.min(CHART_H - d.r - 4, d.y));
    });

    // --- Draw bubbles ---
    const bubbleGroup = svg.append("g").attr("class", "bubbles");

    const node = bubbleGroup.selectAll(".bubble")
      .data(data, function (d) { return d.ticker; })
      .join("g")
        .attr("class", "bubble")
        .attr("id", function (d) { return "bubble-" + d.ticker; })
        .attr("transform", function (d) {
          return "translate(" + d.x.toFixed(2) + "," + d.y.toFixed(2) + ")";
        })
        .on("click", function (event, d) { onBubbleClick(d); })
        .on("mouseover", function (event, d) { onBubbleHover(event, d, true); })
        .on("mousemove", function (event, d) { onBubbleHover(event, d, false); })
        .on("mouseout",  function ()          { hideTooltip(); });

    // Circle fill
    node.append("circle")
      .attr("r", function (d) { return d.r; })
      .attr("fill", function (d) { return SECTOR_COLOR[d.sector]; })
      .attr("fill-opacity", 0.82)
      .attr("stroke", function (d) { return d3.color(SECTOR_COLOR[d.sector]).darker(0.6); })
      .attr("stroke-width", 1.5);

    // Ticker label (hide if bubble too small)
    node.append("text")
      .attr("class", "bubble-label")
      .attr("font-size", function (d) {
        // Scale font size roughly with radius
        return Math.max(7, Math.min(11, d.r * 0.52)) + "px";
      })
      .text(function (d) { return d.ticker; });

    // --- Legend ---
    const legend = d3.select("#legend");
    SECTOR_ORDER.forEach(function (sector) {
      const item = legend.append("div").attr("class", "legend-item");
      item.append("div")
        .attr("class", "legend-swatch")
        .style("background", SECTOR_COLOR[sector]);
      item.append("span").text(sector);
    });
  }

  /* ============================================================
     DATA TABLE
     ============================================================ */
  function renderTable(data) {
    const tbody = d3.select("#stock-tbody");

    const rows = tbody.selectAll("tr")
      .data(data, function (d) { return d.ticker; })
      .join("tr")
        .attr("id", function (d) { return "row-" + d.ticker; })
        .on("click", function (event, d) { onRowClick(d); });

    // Ticker
    rows.append("td")
      .attr("class", "td-ticker")
      .text(function (d) { return d.ticker; });

    // Full name (truncate in CSS)
    rows.append("td")
      .attr("class", "td-name")
      .attr("title", function (d) { return d.name; })
      .text(function (d) { return d.name; });

    // Sector badge
    rows.append("td")
      .attr("class", "td-sector")
      .append("span")
        .attr("class", "sector-badge")
        .style("background", function (d) { return SECTOR_COLOR[d.sector]; })
        .text(function (d) { return d.sector; });

    // Market cap
    rows.append("td")
      .attr("class", "td-mcap")
      .text(function (d) { return formatMarketCap(d.marketCap); });
  }

  /* ============================================================
     TOOLTIP
     ============================================================ */
  const tooltip = d3.select("#tooltip");

  function onBubbleHover(event, d, isEnter) {
    // No tooltip for ETFs
    if (d.isETF) return;

    const sectorColor = SECTOR_COLOR[d.sector];

    tooltip
      .classed("visible", true)
      .html(
        '<div class="tt-ticker">' + d.ticker + '</div>' +
        '<div class="tt-name">'   + d.name   + '</div>' +
        '<div class="tt-sector"><span style="background:' + sectorColor + '">' +
          d.sector + '</span></div>'
      );

    positionTooltip(event);
  }

  function positionTooltip(event) {
    const tip = tooltip.node();
    const tw = tip.offsetWidth  || 200;
    const th = tip.offsetHeight || 70;
    const vw = window.innerWidth;
    const vh = window.innerHeight;

    let left = event.clientX + 14;
    let top  = event.clientY - 14;

    // Flip left if near right edge
    if (left + tw > vw - 10) left = event.clientX - tw - 14;
    // Flip up if near bottom edge
    if (top + th > vh - 10)  top  = event.clientY - th + 14;

    tooltip
      .style("left", left + "px")
      .style("top",  top  + "px");
  }

  function hideTooltip() {
    tooltip.classed("visible", false);
  }

  /* ============================================================
     SELECTION / CROSS-LINK
     ============================================================ */
  let selectedTicker = null;

  function selectTicker(ticker) {
    // Deselect previous
    if (selectedTicker) {
      d3.select("#bubble-" + selectedTicker).classed("selected", false);
      d3.select("#row-"    + selectedTicker).classed("selected", false);
    }

    if (selectedTicker === ticker) {
      // Toggle off
      selectedTicker = null;
      return;
    }

    selectedTicker = ticker;

    // Highlight bubble
    d3.select("#bubble-" + ticker).classed("selected", true);

    // Highlight and scroll to table row
    const rowEl = document.getElementById("row-" + ticker);
    if (rowEl) {
      d3.select(rowEl).classed("selected", true);
      rowEl.scrollIntoView({ behavior: "smooth", block: "nearest" });
    }
  }

  function onBubbleClick(d) {
    selectTicker(d.ticker);
  }

  function onRowClick(d) {
    selectTicker(d.ticker);
  }

})();
